const cvContent = $("Create Tailored CV Content").item.json;
const qualification = $("Score Job Qualification").item.json;

const cvPdf = $("Upload CV PDF to Baserow").first().json;
const cvTex = $("Upload CV TEX to Baserow").first().json;
const coverPdf = $("Upload Cover Letter PDF to Baserow").first().json;
const coverTex = $("Upload Cover Letter TEX to Baserow").first().json;

const requiredUpload = (upload, label) => {
  if (!upload || typeof upload.name !== "string" || !upload.name.trim()) {
    throw new Error(`${label} did not return a valid Baserow user-file name.`);
  }
  return upload;
};

requiredUpload(cvPdf, "CV PDF upload");
requiredUpload(cvTex, "CV TEX upload");
requiredUpload(coverPdf, "Cover letter PDF upload");
requiredUpload(coverTex, "Cover letter TEX upload");

const rowId = Number($("Create Job Row in Baserow").item.json.id);
if (!Number.isInteger(rowId) || rowId <= 0) {
  throw new Error("The initial Baserow row did not return a valid row ID.");
}

const applicationId = String(cvContent.application_id ?? "application");
const qualificationScore = Number(qualification.qualification_score);
const shouldApply = Boolean(qualification.should_apply);

if (!Number.isInteger(qualificationScore)) {
  throw new Error("qualification_score must be an integer.");
}

return [{
  json: {
    rowId,
    Apply: shouldApply,
    Score: qualificationScore,
    "Cover Letter": [
      {
        "name": coverPdf.name,
        "visible_name": `cover-letter_${applicationId}.pdf`
      },
      {
        "name": coverTex.name,
        "visible_name": `cover-letter_${applicationId}.tex`
      }
    ],
    "CV": [
      {
        "name": cvPdf.name,
        "visible_name": `cv_${applicationId}.pdf`
      },
      {
        "name": cvTex.name,
        "visible_name": `cv_${applicationId}.tex`
      }
    ]
  },
  pairedItem: {
    item: 0
  }
}];

return $input.all().map((item, index) => {
  const job = item.json;
  const jobId = Number(job.jobId);

  if (!Number.isInteger(jobId)) {
    throw new Error(`Job ID at item ${index + 1} must be an integer.`);
  }

  const dateValue = job.publishedAt
    ? String(job.publishedAt).slice(0, 10)
    : new Date().toISOString().slice(0, 10);

  return {
    json: {
      "Job ID": jobId,
      "Date": dateValue,
      "Company Name": job.companyName ?? "",
      "Title": job.jobTitle ?? "",
      "Location": job.location ?? "",
      "Job Description": job.jobDescription ?? "",
      "Contract Type": job.contractType ?? "",
      "Link": job.jobUrl ?? "",
      "Status": "New"
    },
    pairedItem: index
  };
});

const createdRows = $input.all();
const jobs = $("Keep Only New Job").all();

if (createdRows.length !== jobs.length) {
  throw new Error(
    `Created ${createdRows.length} Baserow rows for ${jobs.length} new jobs.`
  );
}

return createdRows.map((item, index) => {
  const createdRow = item.json;
  const job = jobs[index].json;

  if (!createdRow?.id) {
    throw new Error(
      `Baserow row ${index + 1} was created without returning a row ID.`
    );
  }

  return {
    json: {
      ...job,
      baserow_row_id: createdRow.id
    },
    pairedItem: index
  };
});

const qualification = $json;
const rowId = Number(qualification.baserow_row_id);

if (!Number.isInteger(rowId) || rowId <= 0) {
  throw new Error("The saved job context does not contain a valid Baserow row ID.");
}
if (!Number.isInteger(qualification.qualification_score)) {
  throw new Error("qualification_score must be an integer.");
}
if (typeof qualification.should_apply !== "boolean") {
  throw new Error("should_apply must be a boolean.");
}

return [{
  json: {
    rowId,
    Apply: qualification.should_apply,
    Score: qualification.qualification_score
  }
}];

const qualification = $("Score Job Qualification").item.json;
const updatedRow = $input.first().json;

if (!updatedRow?.id) {
  throw new Error("The qualification update did not return the Baserow row.");
}

return [{ json: qualification }];

const input = $input.first();
const isTelegramTest = input.json.__telegram_test === true;
const inputBinary = input.binary ?? {};

const sourceFiles = {
  cv_pdf: inputBinary.cv_pdf ?? $("Download CV PDF for Telegram").first().binary?.cv_pdf,
  cv_tex: inputBinary.cv_tex ?? $("Download CV TEX for Telegram").first().binary?.cv_tex,
  cover_letter_pdf: inputBinary.cover_letter_pdf ?? $("Download Cover Letter PDF for Telegram").first().binary?.cover_letter_pdf,
  cover_letter_tex: inputBinary.cover_letter_tex ?? $("Download Cover Letter TEX for Telegram").first().binary?.cover_letter_tex
};

const archiveFiles = {
  zip_cv_pdf: [sourceFiles.cv_pdf, "MojtabaKanani_CV.pdf", "pdf", "application/pdf"],
  zip_cv_tex: [sourceFiles.cv_tex, "MojtabaKanani_CV.tex", "tex", "text/x-tex"],
  zip_cl_pdf: [sourceFiles.cover_letter_pdf, "MojtabaKanani_CL.pdf", "pdf", "application/pdf"],
  zip_cl_tex: [sourceFiles.cover_letter_tex, "MojtabaKanani_CL.tex", "tex", "text/x-tex"]
};

const basename = (value) => {
  const withoutQuery = String(value ?? "").split(/[?#]/)[0];
  const leaf = withoutQuery.split(/[\\/]/).pop() ?? "";
  try {
    return decodeURIComponent(leaf);
  } catch {
    return leaf;
  }
};

const removeDocumentPrefix = (value) =>
  basename(value)
    .replace(/\.[^.]+$/, "")
    .replace(/^(?:cv|cover[-_ ]?letter)[-_ ]+/i, "")
    .trim();

const fallbackApplicationId = String(
  input.json.application_id ??
  (isTelegramTest
    ? "telegram_test"
    : $("Create Tailored CV Content").first().json.application_id) ??
  "application"
);
const archiveBaseName =
  removeDocumentPrefix(sourceFiles.cv_pdf?.fileName) ||
  removeDocumentPrefix(sourceFiles.cv_tex?.fileName) ||
  removeDocumentPrefix(sourceFiles.cover_letter_pdf?.fileName) ||
  removeDocumentPrefix(sourceFiles.cover_letter_tex?.fileName) ||
  fallbackApplicationId;
const archiveFileName = `${archiveBaseName}.zip`;

const binary = {};
for (const [propertyName, [source, fileName, fileExtension, mimeType]] of Object.entries(archiveFiles)) {
  if (!source) {
    throw new Error(`Missing source file for ZIP entry: ${fileName}`);
  }

  binary[propertyName] = {
    ...source,
    fileName,
    fileExtension,
    mimeType
  };
}

return [{
  json: {
    ...input.json,
    __telegram_test: isTelegramTest,
    archiveFileName
  },
  binary,
  pairedItem: {
    item: 0
  }
}];

const input = $input.first();
const isTelegramTest = $("TEST — Sample Should-Apply Job").isExecuted;
const testItem = isTelegramTest
  ? $("TEST — Sample Should-Apply Job").first()
  : null;
const applicationId = String(
  isTelegramTest
    ? testItem.json.application_id
    : $("Create Tailored CV Content").first().json.application_id ?? "application"
);
const job = isTelegramTest
  ? testItem.json
  : $("Score Job Qualification").first().json;
const sourceBinary = testItem?.binary ?? {};
const inputBinary = input.binary ?? {};
const applicationZip =
  inputBinary.application_zip ??
  $("Build Telegram Application ZIP").first().binary?.application_zip;
const archiveFileName = applicationZip?.fileName ?? `${applicationId}.zip`;

const files = [
  {
    binaryFile: applicationZip,
    propertyName: "application_zip",
    fileName: archiveFileName,
    fileExtension: "zip",
    mimeType: "application/zip"
  },
  {
    binaryFile: sourceBinary.cv_pdf ?? $("Download CV PDF for Telegram").first().binary?.cv_pdf,
    propertyName: "cv_pdf",
    fileName: `cv_${applicationId}.pdf`,
    fileExtension: "pdf",
    mimeType: "application/pdf"
  },
  {
    binaryFile: sourceBinary.cv_tex ?? $("Download CV TEX for Telegram").first().binary?.cv_tex,
    propertyName: "cv_tex",
    fileName: `cv_${applicationId}.tex`,
    fileExtension: "tex",
    mimeType: "text/x-tex"
  },
  {
    binaryFile: sourceBinary.cover_letter_pdf ?? $("Download Cover Letter PDF for Telegram").first().binary?.cover_letter_pdf,
    propertyName: "cover_letter_pdf",
    fileName: `cover-letter_${applicationId}.pdf`,
    fileExtension: "pdf",
    mimeType: "application/pdf"
  },
  {
    binaryFile: sourceBinary.cover_letter_tex ?? $("Download Cover Letter TEX for Telegram").first().binary?.cover_letter_tex,
    propertyName: "cover_letter_tex",
    fileName: `cover-letter_${applicationId}.tex`,
    fileExtension: "tex",
    mimeType: "text/x-tex"
  }
];

return files.map((file, uploadIndex) => {
  if (!file.binaryFile) {
    throw new Error(`Missing Telegram attachment: ${file.propertyName}`);
  }

  Object.assign(file.binaryFile, {
    fileName: file.fileName,
    fileExtension: file.fileExtension,
    mimeType: file.mimeType
  });

  return {
    json: {
      uploadIndex,
      fileName: file.fileName,
      job
    },
    binary: {
      data: file.binaryFile
    },
    pairedItem: {
      item: 0
    }
  };
});

const uploads = $input.all();

if (uploads.length !== 5) {
  throw new Error(`Expected 5 temporary Telegram uploads, received ${uploads.length}`);
}

return uploads.map((item, uploadIndex) => {
  const message = item.json.result ?? item.json;
  const messageId = message.message_id;
  const fileId = message.document?.file_id;

  if (!messageId || !fileId) {
    throw new Error(`Telegram upload ${uploadIndex + 1} did not return a document file_id and message_id`);
  }

  return {
    json: {
      uploadIndex,
      messageId,
      fileId
    },
    pairedItem: {
      item: uploadIndex
    }
  };
});

const cleanupResults = $input.all();
const uploads = $("Capture Telegram Document IDs").all();
const preparedUploads = $("Prepare Telegram Document Uploads").all();

if (cleanupResults.length !== 5 || uploads.length !== 5 || preparedUploads.length !== 5) {
  throw new Error("Unable to prepare the five-document Telegram album");
}

const fileIds = uploads
  .sort((a, b) => a.json.uploadIndex - b.json.uploadIndex)
  .map((item) => item.json.fileId);

return [{
  json: {
    fileIds,
    job: preparedUploads[0].json.job
  }
}];

