={{ (() => {
  const job = $json.job;
  const escapeHtml = (value, fallback = "—") =>
    String(value ?? fallback)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#39;");

  const formatPublishedDate = (value) => {
    const raw = String(value ?? "").trim();
    const isoDate = raw.match(/^(\d{4})-(\d{2})-(\d{2})/);
    const date = isoDate
      ? new Date(Date.UTC(Number(isoDate[1]), Number(isoDate[2]) - 1, Number(isoDate[3])))
      : new Date(raw);

    if (Number.isNaN(date.getTime())) {
      return raw;
    }

    return new Intl.DateTimeFormat("en-US", {
      year: "numeric",
      month: "long",
      day: "numeric",
      timeZone: "UTC"
    }).format(date);
  };

  const jobUrl =
    job.jobUrl ??
    job.job_url ??
    job.source_job?.jobUrl ??
    job.job_context?.jobUrl ??
    (job.jobId ? `https://www.linkedin.com/jobs/view/${encodeURIComponent(job.jobId)}/` : "");

  const lines = [
    `<b>${escapeHtml(job.jobTitle)}</b>`,
    `🏢 <i>${escapeHtml(job.companyName)}</i>`,
    "",
    `📍 <b>Location:</b> ${escapeHtml(job.location)}`,
    `💼 <b>Contract:</b> ${escapeHtml(job.contractType)}`,
    `🎯 <b>Match score:</b> ${escapeHtml(job.qualification_score)}/100`,
    `🆔 <b>Job ID:</b> <code>${escapeHtml(job.jobId)}</code>`
  ];

  if (job.publishedAt) {
    lines.push(`🗓 <b>Published:</b> ${escapeHtml(formatPublishedDate(job.publishedAt))}`);
  }

  if (jobUrl) {
    lines.push("", `🔗 <a href="${escapeHtml(jobUrl)}">View LinkedIn posting</a>`);
  }

  return lines.join("\n");
})() }}

