const createPdf = (title) => {
  const safeTitle = String(title).replace(/([\\()])/g, "\\$1");
  const stream = `BT /F1 18 Tf 72 720 Td (${safeTitle}) Tj ET`;
  const objects = [
    "<< /Type /Catalog /Pages 2 0 R >>",
    "<< /Type /Pages /Kids [3 0 R] /Count 1 >>",
    "<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>",
    "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>",
    `<< /Length ${Buffer.byteLength(stream, "utf8")} >>\nstream\n${stream}\nendstream`
  ];

  let pdf = "%PDF-1.4\n";
  const offsets = [0];
  for (let index = 0; index < objects.length; index++) {
    offsets.push(Buffer.byteLength(pdf, "utf8"));
    pdf += `${index + 1} 0 obj\n${objects[index]}\nendobj\n`;
  }

  const xrefOffset = Buffer.byteLength(pdf, "utf8");
  pdf += `xref\n0 ${objects.length + 1}\n`;
  pdf += "0000000000 65535 f \n";
  for (const offset of offsets.slice(1)) {
    pdf += `${String(offset).padStart(10, "0")} 00000 n \n`;
  }
  pdf += `trailer\n<< /Size ${objects.length + 1} /Root 1 0 R >>\nstartxref\n${xrefOffset}\n%%EOF\n`;
  return Buffer.from(pdf, "utf8").toString("base64");
};

const toBase64 = (value) => Buffer.from(value, "utf8").toString("base64");
const applicationId = "telegram_test_should_apply";

return [{
  json: {
    __telegram_test: true,
    application_id: applicationId,
    should_apply: true,
    qualification_score: 100,
    jobId: "TELEGRAM-TEST-001",
    jobTitle: "Senior Software Engineer — Telegram Test",
    companyName: "Example Company",
    location: "Remote — Canada",
    contractType: "Full-time",
    publishedAt: new Date().toISOString(),
    jobUrl: "https://www.linkedin.com/jobs/"
  },
  binary: {
    cv_pdf: {
      data: createPdf("Sample Tailored CV — Telegram Test"),
      mimeType: "application/pdf",
      fileName: `cv_${applicationId}.pdf`,
      fileExtension: "pdf"
    },
    cv_tex: {
      data: toBase64("\\documentclass{article}\n\\begin{document}\nSample tailored CV for the Telegram album test.\n\\end{document}\n"),
      mimeType: "text/x-tex",
      fileName: `cv_${applicationId}.tex`,
      fileExtension: "tex"
    },
    cover_letter_pdf: {
      data: createPdf("Sample Cover Letter — Telegram Test"),
      mimeType: "application/pdf",
      fileName: `cover-letter_${applicationId}.pdf`,
      fileExtension: "pdf"
    },
    cover_letter_tex: {
      data: toBase64("\\documentclass{letter}\n\\begin{document}\nSample cover letter for the Telegram album test.\n\\end{document}\n"),
      mimeType: "text/x-tex",
      fileName: `cover-letter_${applicationId}.tex`,
      fileExtension: "tex"
    }
  }
}];
